def main():
 import argparse,resource
 parser=argparse.ArgumentParser(allow_abbrev=False,description=__doc__)
 for name in ('bindings','release','output'):parser.add_argument('--'+name,type=Path,required=True)
 parser.add_argument('--release-sha256',required=True);args=parser.parse_args()
 release_ref=ref(args.release);need(release_ref['sha256']==args.release_sha256,'exact one-shot readonly release')
 release=read(release_ref);binding_ref=ref(args.bindings)
 need(args.bindings==BINDING and release['author']=='/root' and release['decision']=='AUTHORIZE_ONE_CONVERSION_POSTJOIN_READONLY_CAPTURE' and release['maximum_invocations']==1 and release['source']==ref(__file__) and release['bindings']==binding_ref and release['output']==str(args.output) and release['native_authority'] is None and release['runtime_authority'] is None,'exact Root readonly source/binding/output, no producer or native grant')
 review=read(release['independent_execution_review']);need(review['decision']=='PASS_EXACT_CONVERSION_POSTJOIN_READONLY_CAPTURE' and review['independent'] is True and review['implementation_ownership'] is False and review['release_payload']=={k:v for k,v in release.items()if k!='independent_execution_review'},'independent exact readonly release')
 need(os.getuid()==os.geteuid()==1000 and os.sched_getaffinity(0)=={0} and 0<resource.getrlimit(resource.RLIMIT_AS)[0]<=2<<30 and 0<resource.getrlimit(resource.RLIMIT_CPU)[0]<=60,'same previously reviewed readonly profile')
 need(args.output==HERE/'actual-frontier-1/OBSERVATION.json' and args.output.parent.is_dir() and not args.output.exists(),'fresh confined result path')
 binding=read(binding_ref);need(binding['query_output_directory']==str(HERE/'actual-frontier-1/commands'),'fresh exact query output path')
 with args.output.open('x')as out:
  try:result=observe()
  except BaseException as error:out.write(json.dumps(dict(status='CONVERSION_FRONTIER_READONLY_FAILED_NO_RETRY',error=repr(error),current_free=False,runtime_authority=None))+'\n');raise
  out.write(json.dumps(result,indent=2)+'\n')
 print(json.dumps(dict(status='CONVERSION_FRONTIER_OBSERVATION_PENDING_JOIN_AND_INDEPENDENT_ACCEPTANCE',output=ref(args.output),current_free=False)))
